use std::io

fn read_trim() -> string {
    match io::read_line() {
        Ok(s) => s.trim().to_string(),
        Err(_) => "",
    }
}

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() as int {
        if keys[i] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let cap: int = read_trim().parse::<int>().unwrap_or(1)
    // index 0 = most recently used
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    loop {
        let line = read_trim()
        if line == "" {
            break
        }
        let parts: Vec<string> = line.split_whitespace().collect()
        let cmd = parts[0]
        if cmd == "put" {
            let k: int = parts[1].parse::<int>().unwrap_or(0)
            let v: int = parts[2].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i >= 0 {
                keys.remove(i as usize)
                vals.remove(i as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() as int > cap {
                let last = keys.len() - 1
                let ek = keys[last]
                keys.remove(last)
                vals.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k: int = parts[1].parse::<int>().unwrap_or(0)
            let i = find(keys, k)
            if i < 0 {
                println("-1")
            } else {
                let v = vals[i as usize]
                keys.remove(i as usize)
                vals.remove(i as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut j = 0
                while j < keys.len() {
                    if j > 0 {
                        out = out + " "
                    }
                    out = out + "${keys[j]}"
                    j += 1
                }
                println(out)
            }
        }
    }
}

